$path = Resolve-Path 'wwwroot/app.js'
$source = [IO.File]::ReadAllText($path, [Text.Encoding]::UTF8)
$editor = @'
function editor(item){
const x=item||{category:'',orderNumber:'',parkName:'',productNumber:'',number:'',name:'',notes:'',dimensions:'',sourcePath:''};
const image=item?.assets?.find(a=>a.kind==='image'),drawing=item?.assets?.find(a=>a.kind==='drawing'),model=item?.assets?.find(a=>a.kind==='model');
const current=a=>a?`<div class="file-current">\u2713 \u0417\u0430\u0433\u0440\u0443\u0436\u0435\u043d: <b>${esc(a.name)}</b></div>`:'';
const orders=(window.__orders||[]).map(o=>`<option value="${esc(o.number)}" ${x.orderNumber===o.number?'selected':''}>${esc(o.number)}${o.parkName?' 3 '+esc(o.parkName):''}</option>`).join('');
const form=`<div class="modal-content"><div class="form-grid">
<div class="field"><label>\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f *</label><input name="category" value="${esc(x.category)}" list="categories" required><datalist id="categories">${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</datalist></div>
<div class="field"><label>\u0413\u0430\u0431\u0430\u0440\u0438\u0442\u044b</label><input name="dimensions" value="${esc(x.dimensions)}" placeholder="6000\u04452200\u04452600"></div>
<div class="field"><label>\u041d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430 *</label><select name="orderNumber" required><option value="">\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u043a\u0430\u0437</option>${orders}<option value="__new">+ \u041d\u043e\u0432\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430</option></select><input class="new-order-input hidden" name="newOrderNumber" placeholder="\u041d\u043e\u0432\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430"><input name="parkName" value="${esc(x.parkName||'')}" placeholder="\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u0440\u043a\u0430"></div>
<div class="field"><label>\u041d\u043e\u043c\u0435\u0440 \u0438\u0437\u0434\u0435\u043b\u0438\u044f *</label><input name="productNumber" value="${esc(x.productNumber||'')}" placeholder="3" required></div>
<div class="field wide"><label>\u041d\u0430\u0438\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u0438\u0435 *</label><input name="name" value="${esc(x.name)}" placeholder="\u041a\u0430\u0447\u0435\u043b\u044c (\u043f\u043e\u0434\u0432\u0435\u0441-\u0434\u0438\u0432\u0430\u043d)" required></div>
<div class="field wide"><label>\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 / \u043f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435</label><textarea name="notes" placeholder="\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f">${esc(x.notes)}</textarea></div>
<div class="field wide"><label>\u041a\u0430\u0440\u0442\u0438\u043d\u043a\u0430-\u0440\u0435\u043d\u0434\u0435\u0440</label>${current(image)}<input name="renderFile" type="file" accept="image/*"><small class="file-replace-note hidden" data-for="renderFile">\u041d\u043e\u0432\u044b\u0439 \u0444\u0430\u0439\u043b \u0437\u0430\u043c\u0435\u043d\u0438\u0442 \u0442\u0435\u043a\u0443\u0449\u0438\u0439</small></div>
<div class="field"><label>\u0427\u0435\u0440\u0442\u0451\u0436 PDF</label>${current(drawing)}<input name="drawingFile" type="file" accept="application/pdf,.pdf"><small class="file-replace-note hidden" data-for="drawingFile">\u041d\u043e\u0432\u044b\u0439 \u0444\u0430\u0439\u043b \u0437\u0430\u043c\u0435\u043d\u0438\u0442 \u0442\u0435\u043a\u0443\u0449\u0438\u0439</small></div>
<div class="field"><label>HTML-\u043c\u043e\u0434\u0435\u043b\u044c</label>${current(model)}<input name="modelFile" type="file" accept="text/html,.html,.htm"><small class="file-replace-note hidden" data-for="modelFile">\u041d\u043e\u0432\u044b\u0439 \u0444\u0430\u0439\u043b \u0437\u0430\u043c\u0435\u043d\u0438\u0442 \u0442\u0435\u043a\u0443\u0449\u0438\u0439</small></div>
<div class="field wide"><label>\u0418\u0441\u0445\u043e\u0434\u043d\u044b\u0439 \u0441\u0435\u0442\u0435\u0432\u043e\u0439 \u043f\u0443\u0442\u044c</label><input name="sourcePath" value="${esc(x.sourcePath)}"></div></div></div>`;
const actions=`<footer class="modal-actions">${item?'<button class="button danger" id="deleteItem">\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0438\u0437\u0434\u0435\u043b\u0438\u0435</button>':'<span></span>'}<div class="button-row"><button class="button" id="cancelEdit">\u041e\u0442\u043c\u0435\u043d\u0430</button><button class="button primary" id="saveItem">\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c</button></div></footer>`;
modal(item?'\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u0438\u0437\u0434\u0435\u043b\u0438\u0435':'\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0438\u0437\u0434\u0435\u043b\u0438\u0435','\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438.',form,actions);
document.querySelector('select[name="orderNumber"]')?.addEventListener('change',e=>{const n=document.querySelector('.new-order-input');n?.classList.toggle('hidden',e.target.value!=='__new');const o=(window.__orders||[]).find(z=>z.number===e.target.value);if(o)document.querySelector('[name="parkName"]').value=o.parkName||''});
['renderFile','drawingFile','modelFile'].forEach(name=>{const input=document.querySelector(`[name="${name}"]`),note=document.querySelector(`[data-for="${name}"]`);input?.addEventListener('change',()=>note?.classList.toggle('hidden',!input.files.length))});
document.querySelector('#cancelEdit').onclick=closeModal;
document.querySelector('#saveItem').onclick=async()=>{const val=n=>document.querySelector(`[name="${n}"]`)?.value.trim()||'',choice=val('orderNumber'),order=choice==='__new'?val('newOrderNumber'):choice,product=val('productNumber');if(!val('category')||!order||!product||!val('name'))return toast('\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u043b\u044f');if(!item&&!document.querySelector('[name="renderFile"]').files.length)return toast('\u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0440\u0435\u043d\u0434\u0435\u0440');const input={category:val('category'),orderNumber:order,parkName:val('parkName'),productNumber:product,number:`${order}.${product}`,name:val('name'),dimensions:val('dimensions'),notes:val('notes'),type:'',analogGroup:'',sourcePath:val('sourcePath')};try{const saved=await api(item?`/api/items/${item.id}`:'/api/items',{method:item?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});for(const field of ['renderFile','drawingFile','modelFile']){const file=document.querySelector(`[name="${field}"]`).files[0];if(file){const fd=new FormData();fd.append('file',file);await api(`/api/items/${saved.id}/files`,{method:'POST',body:fd})}}await refresh();closeModal();openDetail(saved.id);toast('\u0418\u0437\u0434\u0435\u043b\u0438\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e')}catch(e){toast(e.message)}};
if(item)document.querySelector('#deleteItem').onclick=async()=>{if(!confirm('\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0438\u0437\u0434\u0435\u043b\u0438\u0435?'))return;await api(`/api/items/${item.id}`,{method:'DELETE'});closeModal();await refresh()}}
'@
$rx=[regex]::new('function editor\(item\)\{.*?\}\r?\nfunction openDetail',[Text.RegularExpressions.RegexOptions]::Singleline)
if(-not $rx.IsMatch($source)){throw 'editor not found'}
$source=$rx.Replace($source,$editor.Trim()+"`r`nfunction openDetail",1)
[IO.File]::WriteAllText($path,$source,[Text.UTF8Encoding]::new($false))
